<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Private submission review</title><body style="font:17px/1.7 system-ui;max-width:960px;margin:40px auto;padding:24px;background:#f8f7f3;color:#19243d"><a href="/admin/assessments">Back to reviews</a><h1>{{ $assessment->attempt->version->content['meta']['title'] }}</h1><p>{{ $assessment->attempt->user->name }} · Submitted {{ $assessment->attempt->submitted_at }} · Rubric {{ $assessment->rubric_version }}</p>@foreach($assessment->attempt->version->content['sections'] as $section)@if(in_array($section['id'],$assessment->attempt->section_ids))<h2>{{ $section['title'] }}</h2><p style="white-space:pre-wrap">{{ $section['passage'] ?? '' }}</p>@foreach($section['questions'] as $q)<article style="background:white;padding:24px;border:1px solid #ddd;margin:20px 0"><h3>{{ $q['prompt'] }}</h3>@if($q['type']==='writing')<div style="white-space:pre-wrap">{{ $assessment->attempt->answers[$q['id']] ?? 'No response submitted.' }}</div>@else @foreach($assessment->attempt->recordings->where('question_id',$q['id']) as $recording)<audio controls aria-label="Student response" src="{{ URL::temporarySignedRoute('recording.stream',now()->addMinutes(5),['recording'=>$recording->id]) }}"></audio>@endforeach @endif</article>@endforeach @endif @endforeach<p>Scores use four equally weighted criteria. A complete Writing estimate weights Task 2 twice as much as Task 1. This is practice feedback, not an official IELTS result.</p></body></html>
